    lineitem = ctx.get_table("lineitem")
    result = lineitem[(lineitem["l_shipdate"] >= date(1995, 1, 1)) & (lineitem["l_shipdate"] < date(1996, 1, 1))].copy()

    def rank_distribution(df: Any) -> Any:
        df = df.copy()
